{panel:bgColor=#deebff}
h3. Context
* {{src/git-auth.ts:8}} {{gitAuthArgs}} The host check is a substring match, so a remote URL such as {{https://github.com.evil.example/x.git}} passes and receives the service token in an {{Authorization}} header. Any user who can register a repository can collect the token.
* {{src/worktree.ts:15}} {{cloneRepo}} {{cloneRepo}} passes the user-supplied {{remoteUrl}} straight to {{gitAuthArgs}} with the service token, so {{git clone}} sends the token to whatever host the URL names, as long as the URL contains the substring {{github.com}} anywhere.
{panel}

h3. Details
Paths and line numbers refer to commit {{4ef35ce0077924f16ca19a77c0823a644f521bb3}} on main.

{code:javascript}
// src/git-auth.ts:6-13

export function gitAuthArgs(remoteUrl: string, token: string): string[] {
  if (remoteUrl.includes("github.com")) {
    return ["-c", `http.extraHeader=Authorization: Bearer ${token}`];
  }
  return [];
}

{code}

{code:javascript}
// src/worktree.ts:13-18
export async function cloneRepo(repo: Repo): Promise<string> {
  const dest = cachePath(repo.id);
  await exec("git", [...gitAuthArgs(repo.remoteUrl, SERVICE_TOKEN), "clone", repo.remoteUrl, dest]);
  return dest;
}

{code}
